// BUILD THE PROPOSAL. Nothing here spends anything; it turns whatever the agent asked for into a
// concrete, priced, enumerated plan that a human can actually judge — or it REFUSES.
//
// Design rule for this node: the human is about to authorise real money, so the proposal must
// state the exact lead count, the exact credit cost, and exactly which people. A proposal that
// cannot state all three is not approvable, and this node throws rather than posting it. An
// unstated cost is itself a refusal — a human cannot approve a number they were never given.
//
// Everything the caller sends is UNTRUSTED. In particular the caller's own claim about the cost
// is never used: the price is computed from the final lead list, after dedupe and after the cap.
// If the caller's claim disagrees with the truth, that disagreement is shown to the human.

// ---- Hard cap, independent of what the caller asks for ---------------------------------------
// 10, deliberately BELOW VIO-source-leads' sourcing cap of 25, for three reasons:
//   1. Sourcing is free and revealing is not. The spend step must be strictly narrower than the
//      free step, so a full sourced page can never be revealed on one human decision.
//   2. Worst case per approval is bounded at 10 lead credits. A mistake costs 10, not 25.
//   3. A human can genuinely read and judge 10 names in a Slack message. At 25 the list stops
//      being reviewed and starts being scrolled past, and then the approval is theatre.
const MAX_LEADS_PER_CALL = 10;
const CREDITS_PER_LEAD = 1;          // Apollo people/match: one lead credit per lead, per call.

// Apollo person ids from the free search. Constrained rather than merely stringified: this value
// goes into an outbound request body, so anything outside this shape is refused, not sanitised.
const APOLLO_ID = /^[A-Za-z0-9_-]{6,64}$/;

// A caller asking for a phone/direct-dial reveal is asking for something this tool must never do.
// Silently ignoring it would leave the agent believing it might have got one. Refuse loudly.
const PHONE_INTENT = /reveal[_\-\s]?(personal[_\-\s]?)?(phone|mobile|number)|request[_\-\s]?(phone|direct[_\-\s]?dial)|reveal[_\-\s]?direct[_\-\s]?dial/i;

// FNV-1a 32-bit. Not a security hash — it only has to CHANGE when the approved list changes, so
// that the spend step can prove the leads it is about to reveal are the leads the human read.
const fingerprint = (ids) => {
  const s = ids.length + '|' + ids.join(',');
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return 'fp' + (h >>> 0).toString(16).padStart(8, '0');
};

const clean = (v, cap) => (typeof v === 'string'
  ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap) : '');

// ---- Unwrap the caller ------------------------------------------------------------------------
// toolWorkflow hands the LLM's argument over as `query`, sometimes as an object and sometimes as
// a JSON string. Accept both; accept nothing else.
const item = $input.first().json || {};
let q = item.query !== undefined ? item.query : item;
if (typeof q === 'string') {
  try { q = JSON.parse(q); }
  catch (e) { throw new Error('REFUSED: input was a string that is not JSON. Send {"product":"...","leads":[{"apollo_id":"..."}]}'); }
}
if (!q || typeof q !== 'object' || Array.isArray(q)) {
  throw new Error('REFUSED: input must be an object with product + leads');
}

// Scanned as KEY NAMES (recursively) plus the caller's own top-level instructions — deliberately
// NOT as a blind JSON.stringify of everything. Apollo's free search puts the literal string
// "Maybe: please request direct dial via people/bulk_match" in has_direct_phone, so stringifying a
// raw lead would refuse a perfectly innocent list. A gate that misfires gets switched off.
const keyNames = (v, acc = []) => {
  if (Array.isArray(v)) { v.forEach((x) => keyNames(x, acc)); }
  else if (v && typeof v === 'object') {
    for (const [k, x] of Object.entries(v)) { acc.push(k); keyNames(x, acc); }
  }
  return acc;
};
const ownWords = Object.entries(q)
  .filter(([k, v]) => k !== 'leads' && (typeof v === 'string' || typeof v === 'number'))
  .map(([, v]) => String(v)).join(' ');
if (PHONE_INTENT.test(keyNames(q).join(' ')) || PHONE_INTENT.test(ownWords)) {
  throw new Error('REFUSED: this tool reveals EMAIL ONLY and cannot request a phone or direct dial. '
    + 'Mobile/dial credits are scarce and reserved; remove the phone request and ask again.');
}

const product = clean(q.product, 40) || 'unspecified product';

// ---- Enumerate the leads ----------------------------------------------------------------------
const rawLeads = q.leads;
if (!Array.isArray(rawLeads) || rawLeads.length === 0) {
  throw new Error('REFUSED: no leads supplied. Reveal is per-lead and priced per-lead, so there is '
    + 'nothing to price and nothing to describe.');
}

// Every lead must carry Apollo's OWN person id from the free search. engine.py's apollo_reveal()
// matches on `id` for exactly this reason: matching on a name or an email guess is ambiguous, and
// an ambiguous match spends a credit on the wrong person. One bad lead refuses the whole call
// rather than quietly shrinking a list the human is about to read.
const normalised = rawLeads.map((l, i) => {
  if (!l || typeof l !== 'object' || Array.isArray(l)) {
    throw new Error(`REFUSED: lead ${i + 1} is not an object`);
  }
  const id = typeof l.apollo_id === 'string' ? l.apollo_id.trim()
    : (typeof l.id === 'string' ? l.id.trim() : '');
  if (!APOLLO_ID.test(id)) {
    throw new Error(`REFUSED: lead ${i + 1} has no usable Apollo person id `
      + `(got ${JSON.stringify(l.apollo_id !== undefined ? l.apollo_id : l.id)}). `
      + 'Reveal matches on the id returned by the free search — never on a name.');
  }
  const first = clean(l.first_name, 60);
  const last = clean(l.last_name, 60) || clean(l.last_name_obfuscated, 60);
  return {
    apollo_id: id,
    name: (first + ' ' + last).trim() || '(name withheld by free search)',
    title: clean(l.title, 60) || '(role unknown)',
    company: clean(l.company, 60) || '(company unknown)',
  };
});

// Dedupe by id BEFORE pricing. The same person twice is two credits for one address.
const seen = new Set();
const unique = normalised.filter((l) => (seen.has(l.apollo_id) ? false : (seen.add(l.apollo_id), true)));
const deduped_out = normalised.length - unique.length;

// Cap. Applied to the list, not to a number the caller passed, so no `limit` argument can widen it.
const leads = unique.slice(0, MAX_LEADS_PER_CALL);
const capped_out = unique.length - leads.length;

const count = leads.length;
const credits = count * CREDITS_PER_LEAD;
if (!Number.isInteger(credits) || credits < 1) {
  throw new Error('REFUSED: cost could not be computed, so there is nothing to approve');
}

// The caller's own claim, if any, is reported but never used.
const claimNum = (v) => (typeof v === 'number' && Number.isFinite(v) ? v
  : (typeof v === 'string' && /^\d+$/.test(v.trim()) ? Number(v.trim()) : null));
const claimed = claimNum(q.cost) ?? claimNum(q.credits) ?? claimNum(q.estimated_credits) ?? claimNum(q.limit);
const claimMismatch = claimed !== null && claimed !== credits;

const companies = new Set(leads.map((l) => l.company)).size;
const fp = fingerprint(leads.map((l) => l.apollo_id));

// ---- What the human sees ----------------------------------------------------------------------
// The count and the cost are repeated in `action` and `cost`, which ask-human caps SEPARATELY at
// 200 chars each. `detail` is capped at 1500, so truncation of the lead list can never hide the
// price — the two numbers that authorise the spend live outside the truncatable field.
const warnings = [];
if (capped_out > 0) {
  warnings.push(`:warning: You asked for ${unique.length}. The hard cap for one reveal is `
    + `${MAX_LEADS_PER_CALL}, so ${capped_out} were dropped. Only the ${count} listed below are covered `
    + 'by this approval; the rest need a separate one.');
}
if (deduped_out > 0) {
  warnings.push(`:information_source: ${deduped_out} duplicate lead(s) removed before pricing.`);
}
if (claimMismatch) {
  warnings.push(`:rotating_light: The agent stated a cost of ${claimed}, but the real cost is `
    + `${credits} credit(s). The number below is the computed one — judge that, not the agent's.`);
}

const roster = leads.map((l, i) =>
  `${String(i + 1).padStart(2)}. ${(l.name + ' · ' + l.title + ' · ' + l.company).slice(0, 66)} [${l.apollo_id}]`
).join('\n');

const detail = [
  `*Reveal plan — ${product}*`,
  `Leads to reveal: *${count}*`,
  `Apollo lead credits to be spent: *${credits}* (${CREDITS_PER_LEAD} per lead, charged on the attempt whether or not an address comes back)`,
  'Reveals *email only*. This tool has no phone parameter and cannot request a mobile or direct dial.',
  `Plan fingerprint: ${fp} — the spend step re-checks it and aborts if the list changed after you approved.`,
  warnings.length ? '\n' + warnings.join('\n') : '',
  '\nThe exact people:',
  roster,
  '\nApproving spends real money. Rejecting spends nothing and reveals nothing.',
].filter(Boolean).join('\n');

const plan = {
  product, leads, count, credits,
  cap: MAX_LEADS_PER_CALL,
  credits_per_lead: CREDITS_PER_LEAD,
  requested: rawLeads.length,
  deduped_out, capped_out,
  claimed_cost: claimed,
  claim_mismatch: claimMismatch,
  fingerprint: fp,
};

// `query` is the shape VIO-agent-tool-ask-human's Shape Proposal reads. `plan` rides along and is
// ignored there; the spend step reads it back out of THIS node, not out of the approval.
return [{ json: {
  query: {
    action: `Reveal ${count} Apollo email address(es) for ${product} — spends ${credits} lead credit(s)`.slice(0, 200),
    cost: `${credits} Apollo lead credit(s) — ${CREDITS_PER_LEAD} per lead, charged on attempt. Email only; no phone credit.`.slice(0, 200),
    touches: `${count} real ${count === 1 ? 'person' : 'people'} at ${companies} ${companies === 1 ? 'company' : 'companies'}. Revealing unlocks their email address; it does NOT message them.`.slice(0, 400),
    detail,
    prior_feedback: clean(q.prior_feedback, 1000),
  },
  plan,
} }];

// READ THE HUMAN'S DECISION. FAIL CLOSED.
//
// Input is whatever VIO-agent-tool-ask-human's own single exit returned. That sub-workflow already
// fails closed; this node does NOT trust it to have done so, because a sub-workflow can be edited,
// swapped, or replaced by a stub, and this is the last node before money.
//
// TWO independent facts must agree — `approved === true` AND `outcome === 'approve'` — exactly the
// narrowing rule ask-human's exit uses. That is deliberate duplication: an "adjust" that somehow
// carried approved:true, or an approval whose outcome was rewritten, reads as DENIED here.
//
// Written as an identity comparison against the boolean literal, never as `!!x` or `x == true`.
// A truthy string, the number 1, a non-empty array, a missing field — none of them approve.
//
// If this ever denies a genuine Slack approval, the sub-workflow's OUTPUT SHAPE changed. Fix the
// reader. Never loosen the check.
const j = $input.item.json || {};

const rawApproved = Object.prototype.hasOwnProperty.call(j, 'approved') ? j.approved : undefined;
const rawOutcome = Object.prototype.hasOwnProperty.call(j, 'outcome') ? j.outcome : undefined;

const approved = rawApproved === true && rawOutcome === 'approve';

let outcome, reason;
if (approved) {
  outcome = 'approve';
  reason = String(j.reason || 'human approved in Slack');
} else if (rawOutcome === 'adjust') {
  outcome = 'adjust';
  reason = String(j.reason || 'human rejected and asked for changes — NOT an approval');
} else if (rawApproved === false || rawOutcome === 'deny') {
  outcome = 'deny';
  reason = String(j.reason || 'human declined in Slack');
} else {
  outcome = 'deny';
  reason = 'no usable decision from the approval step '
    + `(approved=${JSON.stringify(rawApproved)}, outcome=${JSON.stringify(rawOutcome)}) — treated as DENIED`;
}

return { json: {
  approved,
  outcome,
  reason,
  feedback: (outcome === 'adjust' && typeof j.feedback === 'string') ? j.feedback.slice(0, 1000) : '',
  decided_at: String(j.decided_at || new Date().toISOString()),
} };

// AUTHORISE THE SPEND. This is the node that builds the Apollo request bodies, and it is the only
// node in the workflow that can. Read the four properties below before changing anything here.
//
// 1. IT THROWS RATHER THAN ROUTES. It does not return "nothing to do" on a non-approval — it
//    raises, which aborts the execution. A node that quietly emits zero items on the unhappy path
//    is one careless edit away from emitting one.
// 2. IT DOES NOT TRUST ITS OWN POSITION IN THE GRAPH. It re-reads the decision from
//    `Verify Approval (fail closed)` instead of assuming the IF node routed correctly. Rewire the
//    graph so this node sits on the deny branch and it still refuses.
// 3. THE APOLLO NODE HAS NO BODY AND NO URL WITHOUT IT. Both `apollo_body` and `apollo_url` are
//    created here and nowhere else, and the HTTP node reads both from `$json`. If this node never
//    runs, the HTTP node receives zero input items and therefore never executes at all; if it is
//    reached with foreign data, the URL expression resolves to undefined and the request fails
//    before it can leave the box. There is no hardcoded endpoint on the HTTP node to fall back to.
// 4. THE APPROVED LIST IS THE REVEALED LIST. The fingerprint the human was shown is recomputed
//    here from the ids about to be sent, so a plan edited between the ask and the spend aborts.
//
// EMAIL ONLY. The body is built field by field from literals — the caller's lead object is never
// spread into it — so there is no key a caller could add. The assertion below then re-checks the
// finished body and throws if any phone/dial/mobile key ever appears, which is what would catch a
// future edit that added one.

const APOLLO_MATCH_URL = 'https://api.apollo.io/api/v1/people/match';
const MAX_LEADS_PER_CALL = 10;       // must equal Build Proposal's cap; asserted below
const CREDITS_PER_LEAD = 1;
const PHONE_KEY = /phone|dial|mobile|sms|call/i;

const fingerprint = (ids) => {
  const s = ids.length + '|' + ids.join(',');
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return 'fp' + (h >>> 0).toString(16).padStart(8, '0');
};

// ---- 1. The decision, re-read from source -----------------------------------------------------
const verdict = $('Verify Approval (fail closed)').first().json || {};
if (verdict.approved !== true || verdict.outcome !== 'approve') {
  throw new Error('REFUSED: reached the reveal step without a boolean-true human approval '
    + `(approved=${JSON.stringify(verdict.approved)}, outcome=${JSON.stringify(verdict.outcome)}). `
    + 'No Apollo credit was spent.');
}

// ---- 2. The plan, re-read from the node the human's message was rendered from -----------------
const proposal = $('Build Proposal (fail closed)').first().json || {};
const plan = proposal.plan;
if (!plan || typeof plan !== 'object' || !Array.isArray(plan.leads) || plan.leads.length === 0) {
  throw new Error('REFUSED: approval carries no enumerated plan — nothing was described, so nothing is approved');
}

// ---- 3. The cap, re-applied at the point of spend ---------------------------------------------
// Build Proposal already capped. This is not redundant: the cap must hold at the node that spends,
// not only at the node that describes, so no future path can hand a longer list straight to Apollo.
if (plan.leads.length > MAX_LEADS_PER_CALL) {
  throw new Error(`REFUSED: ${plan.leads.length} leads exceeds the hard cap of ${MAX_LEADS_PER_CALL} `
    + 'per reveal. The cap is not a caller preference.');
}
if (plan.cap !== undefined && plan.cap !== MAX_LEADS_PER_CALL) {
  throw new Error(`REFUSED: cap disagreement — the proposal was built with a cap of ${plan.cap}, `
    + `this node enforces ${MAX_LEADS_PER_CALL}. Fix both to the same number.`);
}

// ---- 4. The cost, re-derived from the actual list ---------------------------------------------
// An unstated or wrong cost is a refusal: whatever the human saw must equal what the list costs.
const trueCost = plan.leads.length * CREDITS_PER_LEAD;
if (!Number.isInteger(plan.credits) || plan.credits < 1 || plan.credits !== trueCost) {
  throw new Error(`REFUSED: the approved cost (${JSON.stringify(plan.credits)}) does not equal the `
    + `cost of the approved list (${trueCost}). A cost the human did not see is not approved.`);
}

// ---- 5. The list is the list that was approved ------------------------------------------------
const ids = plan.leads.map((l) => (l && typeof l.apollo_id === 'string' ? l.apollo_id : ''));
if (ids.some((id) => !id)) {
  throw new Error('REFUSED: a lead in the approved plan has no Apollo person id. Reveal matches on '
    + 'the id from the free search; matching any other way spends a credit on the wrong person.');
}
const fp = fingerprint(ids);
if (plan.fingerprint !== fp) {
  throw new Error(`REFUSED: the lead list changed after it was approved (shown ${plan.fingerprint}, `
    + `about to send ${fp}). Ask again with the list you actually intend to reveal.`);
}

// ---- 6. Build the bodies ----------------------------------------------------------------------
const items = plan.leads.map((l, i) => {
  // Literal construction. Note there is NO spread of `l` — the only caller-derived value that
  // reaches Apollo is the id, and it was shape-checked in Build Proposal.
  const body = { id: l.apollo_id, reveal_personal_emails: true };

  const offending = Object.keys(body).filter((k) => PHONE_KEY.test(k));
  if (offending.length) {
    throw new Error(`REFUSED: reveal body would request ${offending.join(', ')}. This tool is email `
      + 'only; mobile/direct-dial credits are scarce and reserved for confirmed positive replies.');
  }
  if (JSON.stringify(Object.keys(body).sort()) !== '["id","reveal_personal_emails"]') {
    throw new Error('REFUSED: reveal body carries unexpected keys — ' + Object.keys(body).join(', '));
  }

  return { json: {
    apollo_url: APOLLO_MATCH_URL,
    apollo_body: body,
    seq: i + 1,
    apollo_id: l.apollo_id,
    name: l.name,
    title: l.title,
    company: l.company,
    plan_fingerprint: fp,
    approved_at: String(verdict.decided_at || ''),
  } };
});

return items;

// RECONCILE. Every lead that was authorised gets a row here, whatever happened to it.
//
// The failure this node exists to prevent: Apollo answers for 8 of 10 leads, the workflow returns
// 8 rows, and the two that vanished look like leads that were never asked for. Credits were spent
// on them either way. So the loop below walks the AUTHORISED list — never the response list — and
// a lead with no response becomes a row with status `no_result`, not an absence.
//
// Cost is reported as ATTEMPTS, not successes. Apollo charges for the call, so a lead that came
// back empty or errored is not free and must never be reported as free.
//
// One more check worth its weight: Apollo's response is matched back by `person.id`. If Apollo
// answers with a DIFFERENT person than the one requested, the email is discarded rather than
// attributed. Emailing the wrong human because two records got crossed is worse than a miss.

const authorised = $('Authorize Reveal (fail closed)').all().map((i) => i.json || {});
const plan = ($('Build Proposal (fail closed)').first().json || {}).plan || {};
const results = $input.all().map((i) => i.json || {});

const requestedIds = new Set(authorised.map((a) => a.apollo_id));
const LOCKED = /^email_not_unlocked/i;

const rows = authorised.map((a, i) => {
  const r = results[i];
  const base = {
    seq: a.seq, apollo_id: a.apollo_id, name: a.name, title: a.title, company: a.company,
    contact_email: '', status: '', note: '',
  };

  // The item never came back at all — the HTTP node produced fewer items than it was given.
  if (r === undefined) {
    return { ...base, status: 'no_result',
      note: 'no response item for this lead. The credit may still have been charged — check Apollo usage.' };
  }

  // onError: continueRegularOutput turns a failed call into an item carrying `error`.
  if (r.error !== undefined || r.__error !== undefined) {
    const e = r.error || r.__error;
    return { ...base, status: 'failed',
      note: String((e && (e.message || e.description)) || e || 'request failed').slice(0, 300) };
  }

  const person = (r.person && typeof r.person === 'object') ? r.person : null;
  if (!person) {
    return { ...base, status: 'no_person', note: 'Apollo returned no person object for this lead' };
  }

  const returnedId = typeof person.id === 'string' ? person.id : '';
  if (returnedId && returnedId !== a.apollo_id) {
    return { ...base, status: 'mismatch',
      note: `Apollo answered with person ${returnedId}, not the requested ${a.apollo_id}. `
        + 'Address discarded rather than attributed to the wrong person.' };
  }

  const email = typeof person.email === 'string' ? person.email.trim() : '';
  if (!email) return { ...base, status: 'no_email', note: 'matched, but Apollo holds no email address' };
  if (LOCKED.test(email)) {
    return { ...base, status: 'locked',
      note: 'Apollo returned its email_not_unlocked placeholder — the address was not released' };
  }
  if (!email.includes('@')) {
    return { ...base, status: 'no_email', note: 'Apollo returned a value that is not an address' };
  }
  return { ...base, contact_email: email, status: 'revealed', note: '' };
});

// Anything Apollo sent back that we did not ask for. Should always be empty; if it is not, the
// pairing above is unsafe and the run must be treated as suspect rather than trusted.
const unrequested = results
  .map((r) => (r && r.person && typeof r.person.id === 'string' ? r.person.id : ''))
  .filter((id) => id && !requestedIds.has(id));

const by = (s) => rows.filter((x) => x.status === s).length;
const attempted = authorised.length;
const revealed = by('revealed');
const missing_results = Math.max(0, attempted - results.length);
const extra_results = Math.max(0, results.length - attempted);

const problems = rows.filter((x) => x.status !== 'revealed').length;
const accounted_for = rows.length;
const complete = accounted_for === attempted
  && (!plan.count || accounted_for === plan.count)
  && missing_results === 0 && extra_results === 0 && unrequested.length === 0;

return [{ json: {
  approved: true,
  outcome: 'approve',
  product: plan.product || '',
  plan_fingerprint: plan.fingerprint || '',
  cap: plan.cap,
  // Conservative on purpose: every attempt is assumed billable, because Apollo bills the call.
  credits_committed: attempted,
  attempted,
  emails_revealed: revealed,
  failed: by('failed') + by('no_result'),
  locked: by('locked'),
  no_email: by('no_email') + by('no_person'),
  mismatched: by('mismatch'),
  missing_results,
  extra_results,
  unrequested_ids: unrequested,
  accounted_for,
  complete,
  ok: complete && problems === 0,
  leads: rows,
  reason: complete
    ? `${revealed}/${attempted} revealed; every authorised lead is accounted for`
    : `INCOMPLETE — ${accounted_for}/${attempted} rows, ${missing_results} lead(s) with no response. `
      + 'Credits may have been spent on them; reconcile against Apollo usage before re-running.',
} }];

// NOT APPROVED. This branch has no Apollo credential, no request body, and no connection to the
// HTTP node — it exists so a refusal is a reported outcome the agent can act on rather than a
// silent dead end. It reads the plan only to say what was NOT done.
const verdict = $('Verify Approval (fail closed)').first().json || {};
const plan = ($('Build Proposal (fail closed)').first().json || {}).plan || {};

const outcome = verdict.outcome === 'adjust' ? 'adjust' : 'deny';

const NEXT = {
  adjust: 'NOT APPROVED. The human rejected this and gave an adjustment. Revise the lead list to '
    + 'follow the feedback, then call reveal_contacts again and pass the feedback as prior_feedback. '
    + 'You still hold no approval and no address was revealed.',
  deny: 'DENIED. No Apollo credit was spent and no address was revealed. Do not re-ask for the same '
    + 'reveal. Log the reason and report it.',
};

return [{ json: {
  approved: false,
  outcome,
  product: plan.product || '',
  plan_fingerprint: plan.fingerprint || '',
  cap: plan.cap,
  credits_committed: 0,
  attempted: 0,
  emails_revealed: 0,
  failed: 0, locked: 0, no_email: 0, mismatched: 0,
  missing_results: 0, extra_results: 0, unrequested_ids: [],
  accounted_for: 0,
  complete: true,
  ok: false,
  leads: [],
  feedback: typeof verdict.feedback === 'string' ? verdict.feedback : '',
  reason: String(verdict.reason || 'no approval — treated as DENIED'),
  next: NEXT[outcome],
} }];

// SINGLE EXIT. Both branches converge here, so this is the last word the calling agent hears.
// It NARROWS and never widens: `approved` survives only if two independent facts still agree.
//
// It also refuses to launder an accounting contradiction. If this node is ever handed a result
// that says "not approved" while also reporting spent credits, it does NOT zero the numbers to
// make the shape tidy — money that left the building has to stay visible. It flags it instead.
//
// Strings are control-char scrubbed: n8n serialises a workflow result with RAW control characters,
// which strict JSON parsers reject (found live 2026-08-16).
const scrub = (v) => Array.isArray(v) ? v.map(scrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]))
  : (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);

const j = $input.first().json || {};
const approved = j.approved === true && j.outcome === 'approve';
const outcome = approved ? 'approve' : (j.outcome === 'adjust' ? 'adjust' : 'deny');

const spent = Number(j.credits_committed) || 0;
const revealed = Number(j.emails_revealed) || 0;
const integrity = (!approved && (spent > 0 || revealed > 0))
  ? 'INTEGRITY ERROR: credits were committed or addresses revealed without an approval. '
    + 'Do not use this output. Investigate the workflow wiring immediately.'
  : '';

const NEXT = {
  approve: 'Revealed addresses are in `leads[].contact_email` (status "revealed" only). Verify them '
    + 'with Reoon before sending anything. Rows with any other status cost a credit and produced no '
    + 'usable address — do not retry them without a fresh approval.',
  adjust: j.next || 'NOT APPROVED — revise and ask again.',
  deny: j.next || 'DENIED — stop.',
};

// The upstream fields are spread FIRST and the narrowed verdict is written LAST, on purpose:
// whatever an upstream node claims about `approved`, the value that leaves this workflow is the
// one computed above. Written the other way round, a malformed upstream would overwrite it.
return [{ json: scrub({
  ...j,
  ok: Boolean(j.ok) && !integrity,
  approved,
  outcome,
  integrity_error: integrity,
  next: NEXT[outcome],
  note: 'Apollo people/match, email only. This tool has no phone parameter and cannot spend a '
    + 'mobile or direct-dial credit. Every reveal here passed a human Approve button in Slack; '
    + 'without one the request body is never built and the Apollo node never runs.',
}) }];
